<script setup>
import { t } from '../../utils/language.js'
import { computed, onMounted, ref, watch } from 'vue'
import { loadProfile, profile, profileDetailsUnavailable, profileError, profileImageUrl, profileLoading } from '../../utils/profile'

const imageError = ref(false)
const initials = computed(() => (profile.value?.fullName || profile.value?.id || '?').trim().split(/\s+/).slice(0, 2).map(part => part[0]).join('').toUpperCase())
watch(() => profile.value?.image, () => { imageError.value = false })
onMounted(() => { if (!profile.value && !profileLoading.value) loadProfile() })
</script>

<template>
  <section class="profile-page" aria-labelledby="profile-title">
    <div class="profile-heading"><p class="profile-kicker">{{ t("YOUR ACCOUNT") }}</p><h1 id="profile-title">{{ t("My profile") }}</h1><p>{{ t("Your account details for the coffee workspace.") }}</p></div>
    <div v-if="profileLoading && !profile" class="profile-state" role="status">{{ t("Loading your profile…") }}</div>
    <div v-else-if="profileError" class="profile-state" role="alert"><p>{{ t(profileError) }}</p><button type="button" @click="loadProfile">{{ t("Try again") }}</button><RouterLink to="/login">{{ t("Sign in") }}</RouterLink></div>
    <template v-else-if="profile"><div class="profile-card"><div class="profile-cover"><span>{{ t("FRAPPE COFFEE WORKSPACE") }}</span></div><div class="profile-content"><div class="profile-identity"><div class="profile-avatar"><img v-if="profile.image && !imageError" :src="profileImageUrl(profile.image)" alt="" @error="imageError = true"><span v-else>{{ initials }}</span></div><div class="profile-name"><h2>{{ profile.fullName }}</h2><p>{{ profile.email || profile.id }}</p></div></div><div class="profile-section"><div><p class="profile-kicker">{{ t("ACCOUNT DETAILS") }}</p><h3>{{ t("Your information") }}</h3><p>{{ t("Details from your signed-in Frappe account.") }}</p></div><dl><div><dt>{{ t("Display name") }}</dt><dd>{{ profile.fullName }}</dd></div><div><dt>{{ t("User ID") }}</dt><dd>{{ profile.id }}</dd></div><div v-if="profile.email"><dt>{{ t("Email address") }}</dt><dd>{{ profile.email }}</dd></div></dl></div><p v-if="profileDetailsUnavailable" class="profile-note" role="status">{{ t("Some account details are unavailable. Your user ID is shown.") }}</p></div></div></template>
  </section>
</template>

<style scoped>
.profile-page{width:100%;max-width:820px;margin:0 auto}.profile-heading{margin-bottom:26px}.profile-heading h1{font-size:calc(28px * var(--font-scale, 1))}.profile-heading>p:last-child{margin:9px 0 0;color:#929b90;font-size:calc(14px * var(--font-scale, 1))}.profile-kicker{margin:0 0 9px;color:#8b9b88;font-size:calc(10px * var(--font-scale, 1));font-weight:750;letter-spacing:1.2px}.profile-card,.profile-state{overflow:hidden;border:1px solid #eaede7;border-radius:12px;background:#fff}.profile-cover{height:105px;display:flex;align-items:flex-start;padding:22px 28px;background:#edf3ea;color:#91a38c;font-size:calc(10px * var(--font-scale, 1));font-weight:700;letter-spacing:1.1px}.profile-content{padding:0 30px 30px}.profile-identity{display:flex;align-items:flex-end;gap:17px;margin-top:-32px}.profile-avatar{width:74px;height:74px;flex:none;display:grid;place-items:center;overflow:hidden;border:4px solid #fff;border-radius:18px;background:#345b3e;color:#fff;font-size:calc(22px * var(--font-scale, 1));font-weight:700}.profile-avatar img{width:100%;height:100%;object-fit:cover}.profile-name{min-width:0;padding-bottom:5px}.profile-name h2{margin:0;color:#344234;font-size:calc(20px * var(--font-scale, 1));font-weight:650;overflow-wrap:anywhere}.profile-name p{margin:5px 0 0;color:#929f90;font-size:calc(13px * var(--font-scale, 1));overflow-wrap:anywhere}.profile-section{margin-top:32px;padding-top:25px;border-top:1px solid #edf0eb}.profile-section h3{margin:0;color:#405040;font-size:calc(16px * var(--font-scale, 1));font-weight:650}.profile-section>div>p:last-child{margin:7px 0 0;color:#9aa399;font-size:calc(12px * var(--font-scale, 1))}.profile-section dl{margin:22px 0 0;display:grid;gap:0}.profile-section dl>div{display:grid;grid-template-columns:minmax(120px, 1fr) 2fr;gap:14px;padding:14px 0;border-bottom:1px solid #f0f2ef;font-size:calc(13px * var(--font-scale, 1))}.profile-section dt{color:#94a091}.profile-section dd{margin:0;color:#4a5b49;font-weight:600;overflow-wrap:anywhere}.profile-note{margin:18px 0 0;color:#8a987f;font-size:calc(12px * var(--font-scale, 1));line-height:1.5}.profile-state{padding:50px 24px;text-align:center;color:#879484;font-size:calc(13px * var(--font-scale, 1))}.profile-state button,.profile-state a{display:inline-block;margin:10px 5px 0;padding:9px 13px;border:1px solid #e2e8e0;border-radius:8px;background:#fff;color:#536650;font-size:calc(12px * var(--font-scale, 1));text-decoration:none}@media(max-width:600px){.profile-content{padding:0 20px 24px}.profile-cover{padding:20px}.profile-section dl>div{grid-template-columns:1fr;gap:5px}.profile-heading h1{font-size:calc(25px * var(--font-scale, 1))}}
</style>
